package org.eclipse.amp.amf.examples.escape;

import org.ascape.util.vis.ColorFeature;
import org.ascape.model.CellOccupant;
import org.ascape.model.HostCell;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Display;
import org.eclipse.draw2d.IFigure;
import org.eclipse.draw2d.Shape;
import org.eclipse.draw2d.ColorConstants;

import org.eclipse.jface.viewers.IColorProvider;
import org.eclipse.amp.agf.gef.IFigureProvider;
import org.eclipse.amp.agf.gef.DefaultFigureProvider;
import org.eclipse.amp.agf.gef.Shapes;

/**
 * Simple Draw Java Implementation.
 * 
 * Generated by AMF for model: WikiExample.metaabm in project: org.eclipse.amp.amf.examples.escape 
 */
public class SimpleDrawFigureProvider extends DefaultFigureProvider {

	private static IFigureProvider singleton;

	public IFigure getFigure(Object object) {
		IFigure figure = null;
		Color color = null;
		Individual definition = (Individual) object;
		Individual individualRule = definition;
		if (figure == null) {
			figure = Shapes.createOval();
		}
		color = new Color(Display.getCurrent(),
				(int) (individualRule.getWealth() * 255), (int) (1 * 255),
				(int) (1 * 255));

		figure.setBackgroundColor(color);
		((Shape) figure).setFill(true);
		return figure;
	}

	public static IFigureProvider getDefault() {
		if (singleton == null) {
			singleton = new SimpleDrawFigureProvider();
		}
		return singleton;
	}
}
